import{_ as i,l as s,o as a,c as l,v as t,p as n,x as r,d,i as p,S as T}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"张量分解","description":"","frontmatter":{"title":"张量分解","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/tensor-decomposition.md","filePath":"llm/tensor-decomposition.md","lastUpdated":1789023840000}'),c={name:"llm/tensor-decomposition.md"};function h(E,e,m,_,u,B){const o=s("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="张量分解" tabindex="-1">张量分解 <a class="header-anchor" href="#张量分解" aria-label="Permalink to &quot;张量分解&quot;">​</a></h1><div class="epigraph"><p>把矩阵再劈成多维数组，用 TT 或 Tucker 核去逼近。参数可以再降一截；GPU 上却很少有比两次 GEMM 更合适的核。</p><footer>—— Novikov et al., Tensorizing Neural Networks, NeurIPS 2015；TT 格式见 Oseledets, 2011</footer></div><p><a href="/llm/low-rank-factorization">上一课</a> 用两个矩阵因子压一层。本课把同一层看成 \\(d_1\\times d_2\\times\\cdots\\) 的张量，用 CP / Tucker / Tensor-Train 分解。缺口是：LLM 的线性层天生是矩阵，张量化是<strong>人为 reshape</strong>，表达力与核都要为此交税。后课离开权重，去压提示词。不发明新的 arXiv 编号。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Novikov 等人把全连接权重 reshape 成高阶张量，再用 TT 链乘，参数随阶数几乎线性而不是乘积增长。嵌入表尤其诱人：\\(|V|\\times d\\) 很大，切成若干模上的小核，存储大降。问题立刻有两个。第一，reshape 的切法是超参，切错等于把不该绑在一起的轴绑死。第二，TT 链乘是一串小张量收缩，在 GPU 上通常打不过一个大 GEMM，更打不过上一课的 \\(UV\\)。</p><p>因此张量分解在 LLM 主栈里是嵌入 / 窄层的候选，不是 4096×11008 的 FFN 默认路径。课序要把它标成「存储极端、计算不友好」，避免与 SVD 课比参数量时假装也更快。</p><p><span class="marginnote">CP 分解把张量写成秩一和，优化对初值敏感、易退化。Tucker 有核心张量，更稳也更重。TT 在链长上折中。选型先问有没有收缩核，再问秩。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>嵌入：把词表轴与隐轴拆成多模，训 TT/Tucker 嵌入，或对已有表做分解再微调。线性层：reshape 成四阶再 Tucker，核心尺寸当秩预算。校准目标仍应尽量靠近 \\(WX\\)，而不是张量 Frobenius——与 FWSVD 同一教训，只是优化更难，常退回先 SVD 再把因子张量化，收益有限。</p><p>与量化：<a href="/llm/gptq">GPTQ</a> 假定一层一块矩阵。分解后应对每个因子分别量化，或先收缩再量化——两种误差不可交换，必须选定一条推理路径并沿它校准。</p>',10)),(a(),n(T,null,{default:r(()=>[p(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E7%9F%A9%E9%98%B5%20W%22%5D%20--%3E%20RS%5B%22%E4%BA%BA%E4%B8%BA%20reshape%20%E6%88%90%E9%AB%98%E9%98%B6%22%5D%0A%20%20RS%20--%3E%20DEC%5B%22TT%20%2F%20Tucker%20%2F%20CP%22%5D%0A%20%20DEC%20--%3E%20ST%5B%22%E5%8F%82%E6%95%B0%E4%B8%8B%E9%99%8D%22%5D%0A%20%20DEC%20--%3E%20KER%5B%22%E4%B8%80%E4%B8%B2%E5%B0%8F%E6%94%B6%E7%BC%A9%22%5D%0A%20%20KER%20--%3E%20GPU%5B%22%E5%BE%80%E5%BE%80%E6%85%A2%E4%BA%8E%20UV%20GEMM%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>低秩矩阵假设 \\(W\\) 的奇异谱快衰减。张量秩假设的是<strong>多线性</strong>结构：reshape 后各模上可分。语言模型权重没有先验保证这一结构，所以压缩率好看时，往往已经把不该可分的交互砍掉，算术与长上下文先崩——退化模式与量化课同类，处方却不是加 bit，而是加核心尺寸或退回 SVD。</p><p>训练期直接用 TT 层（而不是事后分解）让优化适应多线性约束，比 PTQ 式张量化更自洽，也更贵，接近再训一小模型。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要在 FFN 上用 TT 只为了报告参数量。不要把张量秩与矩阵 \\(r\\) 横比。服务路径没有融合收缩时，本课不进入部署。下一课提示压缩：权重不动，减的是输入 token。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>张量化是 reshape 加上多线性秩约束，不是 SVD 的自动升级。</li><li>存储可再降；墙钟通常差于低秩两因子。</li><li>嵌入表比宽 FFN 更合适；切轴是超参。</li><li>与 GPTQ 叠必须固定收缩后再量化的顺序。</li><li>出处：Novikov et al., 2015；Oseledets, 2011。</li></ul>',7))])}const P=i(c,[["render",h]]);export{k as __pageData,P as default};
